      "confidence": 0.99
    },
    {
      "category": "open_connection",
      "components": ["FCC2", "NAVC2", "UART3_FCC2", "UART4_FCC2"],
      "pins": ["FCC2.48", "FCC2.73", "NAVC2.31", "NAVC2.47", "UART3_FCC2.3", "UART4_FCC2.3"],
